#include <bits/stdc++.h>
using namespace std;

int board[16];
int used[16];
int cnt;
vector<pair<int,int>> constraints[8]; // for each pair (0..7), list of (pos1,pos2)

// Directions: 0=above, 1=below, 2=left, 3=right
int dr[4] = {-1,1,0,0};
int dc[4] = {0,0,-1,1};

bool canPlace(int pairIdx, int a, int b) {
    // Check if a and b can be placed for this pair given constraints
    for (auto &pr : constraints[pairIdx]) {
        int pos = pr.first;
        int target = pr.second;
        int r = pos/4, c = pos%4;
        int tr = target/4, tc = target%4;
        // determine direction
        int dir = -1;
        if (tr == r-1 && tc == c) dir = 0;
        else if (tr == r+1 && tc == c) dir = 1;
        else if (tr == r && tc == c-1) dir = 2;
        else if (tr == r && tc == c+1) dir = 3;
        else return false; // invalid constraint (shouldn't happen)

        int placedAt = (pos == a || pos == b) ? a : (pos == b ? b : -1);
        if (placedAt == -1) continue;
        // The other card of the pair must be at target relative position
        int other = (placedAt == a) ? b : a;
        int expectedR = (placedAt/4) + dr[dir];
        int expectedC = (placedAt%4) + dc[dir];
        if (other != expectedR*4 + expectedC) return false;
    }
    return true;
}

void backtrack(int idx) {
    if (idx == 8) {
        cnt++;
        return;
    }
    for (int i = 0; i < 16; i++) {
        if (used[i]) continue;
        for (int j = i+1; j < 16; j++) {
            if (used[j]) continue;
            if (!canPlace(idx, i, j)) continue;
            used[i] = used[j] = 1;
            board[i] = board[j] = idx;
            backtrack(idx+1);
            used[i] = used[j] = 0;
        }
    }
}

