#include <bits/stdc++.h>
using namespace std;

/*
We count the number of complete 4x4 boards containing pairs A..H such that:
for each of 4 given relative positions (dr, dc), there exists one pair whose two
cards differ by exactly (dr, dc) in board coordinates.

Interpretation used:
- Input gives 4 vectors (dr, dc), each corresponding to one of the first four
  pairs A, B, C, D.
- The remaining four pairs E, F, G, H are unconstrained.
- Count all distinct labeled boards.

This matches the classic approach:
1) For each constrained pair, enumerate all placements of its two identical cards
   with the required offset.
2) Ensure the 8 occupied cells are disjoint.
3) Fill the remaining 8 cells with E,E,F,F,G,G,H,H:
      8! / (2!)^4 = 2520 ways.
4) Sum over all valid placements.

Input termination:
The statement says input ends with a line containing a single number > 4.
A robust parser is used:
- Read whole lines.
- If a non-empty line contains exactly one integer > 4, stop.
- Otherwise integers are accumulated; every 8 integers form one test case.
*/

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    vector<int> nums;
    string line;

    auto is_blank = [](const string& s) {
        for (char c : s) if (!isspace((unsigned char)c)) return false;
        return true;
    };

    while (getline(cin, line)) {
        if (is_blank(line)) continue;

        stringstream ss(line);
        vector<int> tmp;
        int x;
        while (ss >> x) tmp.push_back(x);

        if (tmp.size() == 1 && tmp[0] > 4) break;

        for (int v : tmp) nums.push_back(v);
    }

    const long long FREE_WAYS = 2520; // 8! / (2!)^4

    int idx = 0;
    while (idx + 7 < (int)nums.size()) {
        vector<pair<int,int>> d(4);
        for (int i = 0; i < 4; ++i) {
            d[i] = {nums[idx], nums[idx + 1]};
            idx += 2;
        }

        vector<vector<pair<int,int>>> placements(4);

        for (int k = 0; k < 4; ++k) {
            int dr = d[k].first, dc = d[k].second;
            for (int r = 0; r < 4; ++r) {
                for (int c = 0; c < 4; ++c) {
                    int r2 = r + dr, c2 = c + dc;
                    if (0 <= r2 && r2 < 4 && 0 <= c2 && c2 < 4) {
                        int a = r * 4 + c;
                        int b = r2 * 4 + c2;
                        placements[k].push_back({a, b});
                    }
                }
            }
        }

        long long ans = 0;

        for (auto p0 : placements[0]) {
            int m0 = (1 << p0.first) | (1 << p0.second);
            for (auto p1 : placements[1]) {
                int m1 = (1 << p1.first) | (1 << p1.second);
                if (m0 & m1) continue;
                int m01 = m0 | m1;
                for (auto p2 : placements[2]) {
                    int m2 = (1 << p2.first) | (1 << p2.second);
                    if (m01 & m2) continue;
                    int m012 = m01 | m2;
                    for (auto p3 : placements[3]) {
                        int m3 = (1 << p3.first) | (1 << p3.second);
                        if (m012 & m3) continue;
                        ans += FREE_WAYS;
                    }
                }
            }
        }

        cout << ans << '\n';
    }

    return 0;
}

