#include <stdio.h>
#include <string.h>

#define N 16
#define FULLMASK ((1 << N) - 1)

static int dr[4], dc[4];
static int pair1[N], pair2[N], pairCnt;
static int used[N];
static long long ans;

/* Generate all unordered cell pairs (a,b), a<b, such that b = a + (dr,dc)
   or a = b + (dr,dc), i.e. the two cells differ by the given relative offset. */
static void build_pairs(int r, int c) {
    pairCnt = 0;
    for (int i = 0; i < 4; i++) {
        for (int j = 0; j < 4; j++) {
            int ni = i + r, nj = j + c;
            if (0 <= ni && ni < 4 && 0 <= nj && nj < 4) {
                int a = i * 4 + j;
                int b = ni * 4 + nj;
                if (a < b) {
                    pair1[pairCnt] = a;
                    pair2[pairCnt] = b;
                    pairCnt++;
                }
            }
        }
    }
}

/* Backtracking:
   We place 8 unlabeled matching pairs first; afterward multiply by 8!
   because labels A..H can be assigned to the 8 chosen pair-placements arbitrarily.
   To avoid counting the same set of 8 pairs in different orders, we enforce that
   the first cell of each chosen pair is increasing. */
static void dfs(int depth, int startIdx) {
    if (depth == 8) {
        ans++;
        return;
    }
    for (int i = startIdx; i < pairCnt; i++) {
        int a = pair1[i], b = pair2[i];
        if (!used[a] && !used[b]) {
            used[a] = used[b] = 1;
            dfs(depth + 1, i + 1);
            used[a] = used[b] = 0;
        }
    }
}

int main(void) {
    int k;
    while (scanf("%d", &k) == 1) {
        if (k > 4) break;

        /* Input consists of k relative positions, each as row col offsets. */
        long long total = 0;
        for (int t = 0; t < k; t++) {
            scanf("%d %d", &dr[t], &dc[t]);
        }

        /* The original task asks for multiple sets of four relative positions.
           If fewer than 4 are given before termination, process exactly k given sets.
           For each relative position, count perfect matchings formed by that offset. */
        for (int t = 0; t < k; t++) {
            build_pairs(dr[t], dc[t]);
            memset(used, 0, sizeof(used));
            ans = 0;
            dfs(0, 0);

            long long fact8 = 40320LL; /* 8! */
            total += ans * fact8;
        }

        printf("%lld\n", total);
    }
    return 0;
}

import sys
import math

fact = [math.factorial(i) for i in range(17)]

def solve():
    data = sys.stdin.read().strip().split()
    idx = 0
    out_lines = []
    while idx < len(data):
        n = int(data[idx])
        idx += 1
        if n > 4:
            break
        constraints = []
        for _ in range(4):
            r1 = int(data[idx]); c1 = int(data[idx+1])
            r2 = int(data[idx+2]); c2 = int(data[idx+3])
            idx += 4
            constraints.append((r1, c1, r2, c2))

        parent = list(range(16))
        size = [1]*16

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a, b):
            ra, rb = find(a), find(b)
            if ra == rb:
                return
            if size[ra] < size[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            size[ra] += size[rb]

        for r1, c1, r2, c2 in constraints:
            pos1 = r1 * 4 + c1
            pos2 = r2 * 4 + c2
            union(pos1, pos2)

        groups = {}
        for i in range(16):
            root = find(i)
            groups[root] = groups.get(root, 0) + 1

        forced_pairs = 0
        singles = 0
        impossible = False
        for sz in groups.values():
            if sz > 2:
                impossible = True
                break
            elif sz == 2:
                forced_pairs += 1
            elif sz == 1:
                singles += 1

        if impossible or singles != 2 * (8 - forced_pairs):
            out_lines.append("0")
        else:
            ans = fact[8] * fact[singles] // (2**(8 - forced_pairs) * fact[8 - forced_pairs])
            out_lines.append(str(ans))

    sys.stdout.write("\n".join(out_lines))

