                int y = Integer.parseInt(parts[i*2 + 1]);
                offsets[i][0] = x;
                offsets[i][1] = y;
            }

            // For the remaining 4 pairs, we need to consider all possible offsets
            // that maintain the same relative positions
            count = 0;
            used = new boolean[16];
            board = new int[4][4];

            // Generate all possible offset combinations for the remaining 4 pairs
            // We need to find all valid offset sets that work with the first 4
            solve(0);

            System.out.println(count);
        }

        sc.close();
    }

    static void solve(int pair) {
        if (pair == 8) {
            count++;
            return;
        }

        // Try to place the first card of the pair
        for (int pos = 0; pos < 16; pos++) {
            int r = pos / 4;
            int c = pos % 4;

            if (used[pos]) continue;

            // Calculate second card position based on offset
            int r2 = r + offsets[pair][0];
            int c2 = c + offsets[pair][1];

            if (r2 < 0 || r2 >= 4 || c2 < 0 || c2 >= 4) continue;

            int pos2 = r2 * 4 + c2;
            if (used[pos2]) continue;

            // Place the pair
            used[pos] = true;
            used[pos2] = true;
            board[r][c] = pair;
            board[r2][c2] = pair;

            solve(pair + 1);

            // Backtrack
            used[pos] = false;
            used[pos2] = false;
            board[r][c] = 0;
            board[r2][c2] = 0;
        }
    }
}

