    static long countInjectiveAssignments(int[] pairType, int[] req) {
        boolean[] used = new boolean[PAIRS];
        return dfsAssign(0, req, pairType, used);
    }

    static long dfsAssign(int idx, int[] req, int[] pairType, boolean[] used) {
        if (idx == 4) return 1;
        long res = 0;
        for (int i = 0; i < PAIRS; i++) {
            if (!used[i] && pairType[i] == req[idx]) {
                used[i] = true;
                res += dfsAssign(idx + 1, req, pairType, used);
                used[i] = false;
            }
        }
        return res;
    }

    static int relationType(int a, int b) {
        for (int t = 0; t < 4; t++) {
            if (((masks[a][t] >> b) & 1) != 0) return t;
        }
        return -1;
    }

    static void precomputeMasks() {
        for (int a = 0; a < N; a++) {
            int r1 = a / 4, c1 = a % 4;
            for (int b = 0; b < N; b++) {
                if (a == b) continue;
                int r2 = b / 4, c2 = b % 4;
                int dr = Math.abs(r1 - r2);
                int dc = Math.abs(c1 - c2);

                if (dr + dc == 1) masks[a][0] |= (1 << b);
                else if (dr == 1 && dc == 1) masks[a][1] |= (1 << b);
                else if ((dr == 1 && dc == 2) || (dr == 2 && dc == 1)) masks[a][2] |= (1 << b);
                else if ((r1 == r2 || c1 == c2) && dr + dc > 1) masks[a][3] |= (1 << b);
            }
        }
    }

    static void generateAllMatchings() {
        int[] partner = new int[N];
        Arrays.fill(partner, -1);
        gen(partner);
    }

    static void gen(int[] partner) {
        int first = -1;
        for (int i = 0; i < N; i++) {
            if (partner[i] == -1) {
                first = i;
                break;
            }
        }
        if (first == -1) {
            int[][] m = new int[PAIRS][2];
            int idx = 0;
            boolean[] seen = new boolean[N];
            for (int i = 0; i < N; i++) {
                if (!seen[i]) {
                    int j = partner[i];
                    m[idx][0] = i;
                    m[idx][1] = j;
                    seen[i] = seen[j] = true;
                    idx++;
                }
            }
            matchings.add(m);
            return;
        }

        for (int j = first + 1; j < N; j++) {
            if (partner[j] == -1) {
                partner[first] = j;
                partner[j] = first;
                gen(partner);
                partner[first] = partner[j] = -1;
            }
        }
    }
}

import java.util.*;

public class Main {
    static int[] board = new int[16];
    static int[] relPos; // required relative positions for pairs 0-7

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            int a = sc.nextInt();
            if (a > 4) break;
            int b = sc.nextInt(), c = sc.nextInt(), d = sc.nextInt();
            // 4 relative positions, each used by 2 pairs
            int[] rp = {a, a, b, b, c, c, d, d};
            relPos = rp;
            Arrays.fill(board, -1);
            System.out.println(solve(0, 0));
        }
    }

    static long solve(int pair, int startCell) {
        if (pair == 8) return 1;
        long count = 0;
        int r = relPos[pair];
        for (int i = startCell; i < 16; i++) {
            if (board[i] != -1) continue;
            int j = i + r;
            if (j >= 16 || board[j] != -1) continue;
            board[i] = pair; board[j] = pair;
            count += solve(pair + 1, (pair % 2 == 0) ? i + 1 : startCell);
            board[i] = -1; board[j] = -1;
        }
        return count;
    }
}
